-- ============================================================================
-- Import Zano Dagim customers from old-site export (יבוא לקוחות וכתובות - זנו דגים.xlsx)
-- Generated 2026-07-27 from 7,068 source rows.
-- Idempotent: safe to re-run. Existing customers (matched by phone, or by email
-- for phone-less rows) are only ENRICHED - empty fields are filled, marketing
-- consent is OR-ed in, nothing is overwritten.
--
-- BEFORE RUNNING: set @SiteId to the Zano Dagim production Site.Id.
-- ============================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @SiteId INT = NULL;  -- <<<< SET ME: Zano Dagim Site.Id >>>>

IF @SiteId IS NULL
    THROW 50000, N'Set @SiteId to the Zano Dagim Site.Id before running.', 1;

DECLARE @AccountId INT = (SELECT AccountId FROM [dbo].[Site] WHERE Id = @SiteId);
IF @AccountId IS NULL
    THROW 50000, N'Site not found for @SiteId.', 1;

-- ----------------------------------------------------------------------------
-- 0. Make the unique phone index filtered so multiple phone-less customers can
--    coexist per site (source has 865 email-only contacts). Lookup code ignores
--    phones shorter than 4 digits, so empty NormalizedPhone rows are never
--    matched by phone anyway.
-- ----------------------------------------------------------------------------
IF EXISTS (SELECT 1 FROM sys.indexes
           WHERE name = N'IX_Customer_SiteId_NormalizedPhone'
             AND object_id = OBJECT_ID(N'[dbo].[Customer]')
             AND has_filter = 0)
BEGIN
    DROP INDEX [IX_Customer_SiteId_NormalizedPhone] ON [dbo].[Customer];
    CREATE UNIQUE INDEX [IX_Customer_SiteId_NormalizedPhone]
        ON [dbo].[Customer] ([SiteId], [NormalizedPhone])
        WHERE [NormalizedPhone] <> N'';
END

-- ----------------------------------------------------------------------------
-- 1. Stage the import rows
-- ----------------------------------------------------------------------------
CREATE TABLE #Import (
    NormPhone  NVARCHAR(50)  NOT NULL,   -- '' = no phone
    Phone      NVARCHAR(50)  NULL,
    Name       NVARCHAR(200) NOT NULL,
    Email      NVARCHAR(200) NULL,
    City       NVARCHAR(200) NULL,
    Street     NVARCHAR(400) NULL,
    Apartment  NVARCHAR(64)  NULL,
    Floor      NVARCHAR(32)  NULL,
    EntryCode  NVARCHAR(64)  NULL,
    DefaultAddr NVARCHAR(500) NULL,
    Notes      NVARCHAR(2000) NULL,
    Marketing  BIT NOT NULL
);

-- ----------------------------------------------------------------------------
-- 2. Enrich existing customers matched by phone (fill empty fields only, OR marketing)
-- ----------------------------------------------------------------------------
BEGIN TRAN;

UPDATE c SET
    c.Name  = CASE WHEN LTRIM(RTRIM(ISNULL(c.Name, N''))) = N'' THEN i.Name ELSE c.Name END,
    c.Email = COALESCE(NULLIF(c.Email, N''), i.Email),
    c.City  = COALESCE(NULLIF(c.City, N''), i.City),
    c.DeliveryStreet       = COALESCE(NULLIF(c.DeliveryStreet, N''), i.Street),
    c.DeliveryApartment    = COALESCE(NULLIF(c.DeliveryApartment, N''), i.Apartment),
    c.DeliveryFloor        = COALESCE(NULLIF(c.DeliveryFloor, N''), i.Floor),
    c.DeliveryEntranceCode = COALESCE(NULLIF(c.DeliveryEntranceCode, N''), i.EntryCode),
    c.DefaultAddress       = COALESCE(NULLIF(c.DefaultAddress, N''), i.DefaultAddr),
    c.Notes = CASE WHEN i.Notes IS NULL OR c.Notes LIKE N'%' + i.Notes + N'%' THEN c.Notes
                   WHEN NULLIF(c.Notes, N'') IS NULL THEN i.Notes
                   ELSE c.Notes + N' | ' + i.Notes END,
    c.MarketingApproval = c.MarketingApproval | i.Marketing,
    c.MarketingEmail    = c.MarketingEmail | i.Marketing,
    c.MarketingSms      = c.MarketingSms | i.Marketing,
    c.UpdatedDate = SYSUTCDATETIME()
FROM [dbo].[Customer] c
JOIN #Import i ON i.NormPhone <> N'' AND c.SiteId = @SiteId AND c.NormalizedPhone = i.NormPhone
WHERE c.IsDeleted = 0;

DECLARE @UpdatedByPhone INT = @@ROWCOUNT;

-- Enrich existing customers matched by email (phone-less import rows only)
UPDATE c SET
    c.City  = COALESCE(NULLIF(c.City, N''), i.City),
    c.DeliveryStreet       = COALESCE(NULLIF(c.DeliveryStreet, N''), i.Street),
    c.DeliveryApartment    = COALESCE(NULLIF(c.DeliveryApartment, N''), i.Apartment),
    c.DeliveryFloor        = COALESCE(NULLIF(c.DeliveryFloor, N''), i.Floor),
    c.DeliveryEntranceCode = COALESCE(NULLIF(c.DeliveryEntranceCode, N''), i.EntryCode),
    c.DefaultAddress       = COALESCE(NULLIF(c.DefaultAddress, N''), i.DefaultAddr),
    c.MarketingApproval = c.MarketingApproval | i.Marketing,
    c.MarketingEmail    = c.MarketingEmail | i.Marketing,
    c.MarketingSms      = c.MarketingSms | i.Marketing,
    c.UpdatedDate = SYSUTCDATETIME()
FROM [dbo].[Customer] c
JOIN #Import i ON i.NormPhone = N'' AND c.SiteId = @SiteId
              AND c.Email IS NOT NULL AND LOWER(c.Email) = LOWER(i.Email)
WHERE c.IsDeleted = 0;

DECLARE @UpdatedByEmail INT = @@ROWCOUNT;

-- ----------------------------------------------------------------------------
-- 3. Insert new customers (phone rows whose phone is unknown at this site,
--    including soft-deleted holders of the phone to respect the unique index)
-- ----------------------------------------------------------------------------
     DeliveryStreet, DeliveryApartment, DeliveryFloor, DeliveryEntranceCode,
     DefaultAddress, Notes, MarketingApproval, MarketingEmail, MarketingSms,
     IsDeleted, CreationTime)
SELECT @AccountId, @SiteId, i.NormPhone, i.Name, i.Email, i.Phone, i.City,
       i.Street, i.Apartment, i.Floor, i.EntryCode,
       i.DefaultAddr, i.Notes, i.Marketing, i.Marketing, i.Marketing,
       0, SYSUTCDATETIME()
FROM #Import i
WHERE i.NormPhone <> N''
  AND NOT EXISTS (SELECT 1 FROM [dbo].[Customer] c  -- includes soft-deleted
                  WHERE c.SiteId = @SiteId AND c.NormalizedPhone = i.NormPhone);

DECLARE @InsertedWithPhone INT = @@ROWCOUNT;

-- Phone-less rows: insert only if no customer at this site already has the email
     DeliveryStreet, DeliveryApartment, DeliveryFloor, DeliveryEntranceCode,
     DefaultAddress, Notes, MarketingApproval, MarketingEmail, MarketingSms,
     IsDeleted, CreationTime)
SELECT @AccountId, @SiteId, N'', i.Name, i.Email, NULL, i.City,
       i.Street, i.Apartment, i.Floor, i.EntryCode,
       i.DefaultAddr, i.Notes, i.Marketing, i.Marketing, i.Marketing,
       0, SYSUTCDATETIME()
FROM #Import i
WHERE i.NormPhone = N''
  AND NOT EXISTS (SELECT 1 FROM [dbo].[Customer] c
                  WHERE c.SiteId = @SiteId
                    AND c.Email IS NOT NULL AND LOWER(c.Email) = LOWER(i.Email));

DECLARE @InsertedNoPhone INT = @@ROWCOUNT;

COMMIT;

PRINT CONCAT(N'Staged rows: ', (SELECT COUNT(*) FROM #Import));
PRINT CONCAT(N'Existing customers enriched (by phone): ', @UpdatedByPhone);
PRINT CONCAT(N'Existing customers enriched (by email): ', @UpdatedByEmail);
PRINT CONCAT(N'New customers inserted (with phone): ', @InsertedWithPhone);
PRINT CONCAT(N'New customers inserted (email-only): ', @InsertedNoPhone);

DROP TABLE #Import;
